:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --text: #e0e0e0;
  --accent: #0f3460;
  --highlight: #e94560;
  --success: #4caf50;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font);
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 4px;
}

.subtitle {
  font-size: 0.95rem;
  opacity: 0.7;
  margin-bottom: 20px;
}

.add-form {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.add-form input {
  flex: 1 1 180px;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--accent);
  background: var(--bg);
  color: var(--text);
  font-size: 1rem;
  font-family: var(--font);
  outline: none;
}

.add-form input:focus-visible {
  border-color: var(--highlight);
  box-shadow: 0 0 0 2px var(--highlight);
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  padding: 10px 16px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-height: 44px;
}

.btn:focus-visible {
  outline: 2px solid var(--highlight);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--highlight);
  color: #fff;
}

.btn.primary:hover {
  background: #d63a52;
}

.btn.start {
  background: var(--success);
  color: #fff;
}

.btn.start:hover {
  background: #45a049;
}

.btn.stop {
  background: var(--highlight);
  color: #fff;
}

.btn.stop:hover {
  background: #d63a52;
}

.btn.remove {
  background: transparent;
  color: var(--highlight);
  border: 1px solid var(--highlight);
  padding: 6px 12px;
  font-size: 0.9rem;
  min-height: 36px;
}

.btn.remove:hover {
  background: var(--highlight);
  color: #fff;
}

.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.task-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg);
  border-radius: 8px;
  padding: 12px;
  gap: 8px;
  flex-wrap: wrap;
}

.task-info {
  flex: 1 1 120px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.task-name {
  font-weight: 600;
  word-break: break-word;
}

.task-time {
  font-variant-numeric: tabular-nums;
  font-size: 0.95rem;
  opacity: 0.8;
}

.task-controls {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}

.empty-msg {
  text-align: center;
  opacity: 0.6;
  margin-top: 12px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  .task-item { flex-direction: column; align-items: stretch; }
  .task-controls { justify-content: flex-end; }
}

const taskList = document.getElementById('task-list');
const emptyMsg = document.getElementById('empty-msg');
const addForm = document.getElementById('add-form');
const newTaskInput = document.getElementById('new-task');

let tasks = [];
let activeTaskId = null;
let timerInterval = null;

function formatTime(ms) {
  const totalSeconds = Math.floor(ms / 1000);
  const mm = String(Math.floor(totalSeconds / 60)).padStart(2, '0');
  const ss = String(totalSeconds % 60).padStart(2, '0');
  return `${mm}:${ss}`;
}

function render() {
  taskList.innerHTML = '';
  emptyMsg.style.display = tasks.length ? 'none' : 'block';

  tasks.forEach(task => {
    const li = document.createElement('li');
    li.className = 'task-item';
    li.dataset.id = task.id;

    const info = document.createElement('div');
    info.className = 'task-info';

    const name = document.createElement('span');
    name.className = 'task-name';
    name.textContent = task.name;

    const time = document.createElement('span');
    time.className = 'task-time';
    time.id = `time-${task.id}`;
    time.textContent = formatTime(task.elapsed);

    info.appendChild(name);
    info.appendChild(time);

    const controls = document.createElement('div');
    controls.className = 'task-controls';

    const toggleBtn = document.createElement('button');
    toggleBtn.type = 'button';
    toggleBtn.className = 'btn ' + (task.isRunning ? 'stop' : 'start');
    toggleBtn.textContent = task.isRunning ? 'Stop' : 'Start';
    toggleBtn.setAttribute('aria-label', `${task.isRunning ? 'Stop' : 'Start'} ${task.name}`);
    toggleBtn.addEventListener('click', () => toggleTask(task.id));

    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'btn remove';
    removeBtn.textContent = 'Remove';
    removeBtn.setAttribute('aria-label', `Remove ${task.name}`);
    removeBtn.addEventListener('click', () => removeTask(task.id));

    controls.appendChild(toggleBtn);
    controls.appendChild(removeBtn);

    li.appendChild(info);
    li.appendChild(controls);
    taskList.appendChild(li);
  });
}

function startTimer() {
  if (timerInterval) clearInterval(timerInterval);
  timerInterval = setInterval(() => {
    const task = tasks.find(t => t.id === activeTaskId);
    if (!task) return;
    const now = Date.now();
    task.elapsed += now - task.lastTick;
    task.lastTick = now;
    const timeEl = document.getElementById(`time-${task.id}`);
    if (timeEl) timeEl.textContent = formatTime(task.elapsed);
  }, 1000);
}

function stopTimer() {
  if (timerInterval) {
    clearInterval(timerInterval);
    timerInterval = null;
  }
}

function toggleTask(id) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;

  if (task.isRunning) {
    // Stop this task
    task.elapsed += Date.now() - task.lastTick;
    task.isRunning = false;
    activeTaskId = null;
    stopTimer();
  } else {
    // Stop any currently running task
    if (activeTaskId !== null) {
      const active = tasks.find(t => t.id === activeTaskId);
      if (active) {
        active.elapsed += Date.now() - active.lastTick;
        active.isRunning = false;
      }
    }
    // Start this task
    task.isRunning = true;
    task.lastTick = Date.now();
    activeTaskId = task.id;
    startTimer();
  }
  render();
}

function removeTask(id) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;
  if (task.isRunning) {
    stopTimer();
    activeTaskId = null;
  }
  tasks = tasks.filter(t => t.id !== id);
  render();
}

addForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const name = newTaskInput.value.trim();
  if (!name) return;

  const task = {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    name,
    elapsed: 0,
    isRunning: false,
    lastTick: 0
  };
  tasks.push(task);
  newTaskInput.value = '';
  newTaskInput.focus();
  render();
});

// Initial render
render();
